/* Tap hero: paid at the stall, then the market carries on.
   - The tap. Every few seconds the woman's phone meets the farmer's reader and a contactless pulse
     leaves the reader: three thin arcs of light that open toward the phone and fade, the way the
     little wave symbol on every card reader says it. A beat later the reader's screen blinks a soft
     green: paid. That is the product, at the counter, in about a second.
   - The breeze. The bunting strung between the poles sways: each string breathes with a slow wave
     that travels along it, and every pennant swings and flaps on its own about its top edge, more
     when a gust comes through. The pennants were lifted out of the painting (and the sky, spire and
     clouds behind them repainted) so the only bunting you see is this moving one; each pennant is
     the painted pennant itself, cut from the original canvas, so it keeps its brushwork.
   - The two pennants knotted against the tent on the left stay painted; tied that close, they barely move.
   All positions are fractions of the painting (kit.X / kit.Y), so they stay put at every size.
   Reduced motion: the bunting hangs still exactly as painted; no pulse. */
(function () {
  var kit = window.StationHeroFx; if (!kit) return;
  var ctx = kit.canvas(1);

  // the bunting: [atlas x, y, w, h, sprite left, top, width, height, pivot x, pivot y, string] (painting fractions)
  var FLAGS = [[0,0,41,51,0.50469,0.48549,0.01432,0.03132,0.51193,0.48993,0],[42,0,40,52,0.525,0.47398,0.01406,0.03178,0.53208,0.47935,0],[83,0,33,45,0.5375,0.46845,0.01146,0.02764,0.54325,0.47335,0],[117,0,42,58,0.54661,0.45693,0.01458,0.03547,0.55385,0.46355,0],[160,0,41,56,0.57552,0.46246,0.01432,0.03409,0.5827,0.46911,1],[202,0,41,52,0.59141,0.47444,0.01432,0.03224,0.59858,0.47974,1],[244,0,45,56,0.60625,0.48319,0.01562,0.03455,0.61396,0.48815,1],[290,0,46,57,0.62578,0.49194,0.01615,0.03501,0.63389,0.4963,1],[337,0,47,55,0.65104,0.50115,0.01641,0.03363,0.65919,0.50479,1],[385,0,46,52,0.67109,0.50576,0.01615,0.03178,0.67928,0.50882,1],[432,0,36,37,0.68542,0.50944,0.0125,0.02257,0.6916,0.51185,1],[469,0,41,44,0.69609,0.5099,0.01432,0.02672,0.70321,0.51193,1],[511,0,49,50,0.71849,0.51036,0.01693,0.0304,0.72698,0.51175,1],[0,59,50,57,0.74609,0.50484,0.01719,0.03501,0.75474,0.50802,1],[51,59,45,56,0.76771,0.50069,0.01562,0.03409,0.77555,0.50405,1],[97,59,50,57,0.78828,0.49332,0.01719,0.03501,0.79686,0.49765,1],[148,59,49,59,0.81172,0.48457,0.01693,0.03639,0.8201,0.48922,1],[198,59,45,58,0.83385,0.47582,0.01562,0.03593,0.84168,0.48042,1],[244,59,48,60,0.85625,0.46384,0.01667,0.03685,0.86458,0.4696,1],[293,59,48,62,0.87396,0.45371,0.01667,0.03823,0.88225,0.45957,1],[342,59,49,64,0.89583,0.43713,0.01693,0.03915,0.9043,0.4442,1],[392,59,48,57,0.92969,0.42561,0.01667,0.03501,0.93802,0.42976,2],[441,59,53,64,0.95104,0.43252,0.01849,0.03915,0.96034,0.43651,2],[495,59,52,57,0.98021,0.44035,0.01797,0.03501,0.98915,0.44248,2]];
  var SEG = [[0.5013, 0.564], [0.5725, 0.9185], [0.9305, 1.0]], FIT = [[-3.925044, 3.578372, -0.313068], [-2.162573, 3.141373, -0.628971], [-1.995714, 4.084452, -1.645137]]; // each string: x range, and y = a x^2 + b x + c in painting fractions
  var atlas = new Image(), ready = false;
  atlas.onload = function () { ready = true; if (kit.reduce) draw(0); };
  atlas.src = "data:image/webp;base64,";

  var READER = [.2400, .6345], PHONE = [.2555, .6150], PERIOD = 4.6;

  function sy(i, x) { var c = FIT[i]; return (c[0] * x + c[1]) * x + c[2]; }
  // how far the string has moved at x (px): zero at the knots, most in the middle of the span
  function sway(i, x, t) {
    if (kit.reduce) return 0;
    var u = (x - SEG[i][0]) / (SEG[i][1] - SEG[i][0]), hump = 4 * u * (1 - u);
    if (i === 2) hump = Math.min(1, 2.2 * u); // this one runs off the edge of the painting, still rising
    var gust = .75 + .25 * Math.sin(t * .31 + 1);
    return hump * gust * kit.dw * (.0016 * Math.sin(t * 1.25 - x * 9) + .0007 * Math.sin(t * 2.1 - x * 17 + 2));
  }

  function blob(x, y, r, rgb, a) {
    if (a <= .003) return;
    var g = ctx.createRadialGradient(x, y, 0, x, y, r);
    g.addColorStop(0, "rgba(" + rgb + "," + a.toFixed(3) + ")");
    g.addColorStop(.45, "rgba(" + rgb + "," + (a * .35).toFixed(3) + ")");
    g.addColorStop(1, "rgba(" + rgb + ",0)");
    ctx.fillStyle = g; ctx.beginPath(); ctx.arc(x, y, r, 0, 6.2832); ctx.fill();
  }

  function draw(t) {
    ctx.clearRect(0, 0, kit.W, kit.H);
    var dw = kit.dw, dh = kit.dh, i, k;

    // strings: painted-rope colour, a hair darker on the underside
    ctx.lineCap = "round";
    for (i = 0; i < SEG.length; i++) {
      var pts = [];
      for (k = 0; k <= 28; k++) {
        var x = SEG[i][0] + (SEG[i][1] - SEG[i][0]) * k / 28;
        pts.push([kit.X(x), kit.Y(sy(i, x)) + sway(i, x, t)]);
      }
      [["rgba(120,112,100,.55)", .0011, .0004], ["rgba(236,232,222,.95)", .0007, 0]].forEach(function (s) {
        ctx.strokeStyle = s[0]; ctx.lineWidth = Math.max(.8, s[1] * dw);
        ctx.beginPath();
        for (var j = 0; j < pts.length; j++) ctx[j ? "lineTo" : "moveTo"](pts[j][0], pts[j][1] + s[2] * dw);
        ctx.stroke();
      });
    }

    // pennants: each swings about its top edge and flaps (foreshortens) as the air lifts it
    if (ready) for (i = 0; i < FLAGS.length; i++) {
      var f = FLAGS[i], px = f[8], py = f[9], ph = i * 1.7;
      var gust = kit.reduce ? 0 : .7 + .3 * Math.sin(t * .31 + 1 - px * 2);
      var th = kit.reduce ? 0 : gust * (.075 * Math.sin(t * 1.9 - px * 11 + ph) + .03 * Math.sin(t * 3.7 + ph * 2.3)) + .03 * gust;
      var flap = kit.reduce ? 1 : 1 - gust * .07 * (.5 + .5 * Math.sin(t * 2.6 - px * 13 + ph));
      ctx.save();
      ctx.translate(kit.X(px), kit.Y(py) + sway(f[10], px, t));
      ctx.rotate(th);
      ctx.scale(1, flap);
      ctx.drawImage(atlas, f[0], f[1], f[2], f[3], (f[4] - px) * dw, (f[5] - py) * dh, f[6] * dw, f[7] * dh);
      ctx.restore();
    }

    if (kit.reduce) return;
    // the tap: three arcs leave the reader toward the phone, then the reader blinks green
    var p = (t + PERIOD - 1.2) % PERIOD, rx = kit.X(READER[0]), ry = kit.Y(READER[1]);
    var ang = Math.atan2(kit.Y(PHONE[1]) - ry, kit.X(PHONE[0]) - rx);
    ctx.globalCompositeOperation = "lighter";
    for (k = 0; k < 3; k++) {
      var q = (p - k * .2) / .95;
      if (q <= 0 || q >= 1) continue;
      var r = (.005 + .016 * q) * dw, a = Math.sin(q * Math.PI) * (1 - q * .35);
      ctx.lineWidth = Math.max(1, .0042 * dw * (1 - q * .4)); ctx.strokeStyle = "rgba(200,235,255," + (.22 * a).toFixed(3) + ")";
      ctx.beginPath(); ctx.arc(rx, ry, r, ang - .62, ang + .62); ctx.stroke();
      ctx.lineWidth = Math.max(.8, .0016 * dw); ctx.strokeStyle = "rgba(245,252,255," + (.8 * a).toFixed(3) + ")";
      ctx.beginPath(); ctx.arc(rx, ry, r, ang - .55, ang + .55); ctx.stroke();
    }
    var g = (p - 1.15) / 1.0;
    if (g > 0 && g < 1) {
      var ga = Math.sin(g * Math.PI); ga = Math.sqrt(ga);
      blob(rx, ry, .016 * dw, "110,230,150", .45 * ga);
      blob(rx, ry, .006 * dw, "200,255,210", .75 * ga);
    }
    ctx.globalCompositeOperation = "source-over";
  }

  kit.onLayout(function () { if (kit.reduce) draw(0); });
  if (kit.reduce) { draw(0); return; }
  kit.loop(draw);
})();
